contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory tos, uint v) public {
        // Precondition: tos length must be positive for the contract to proceed without reverting on the require.
        bool reverted;
        if (tos.length > 0) {
            try c.transfer(from, caddress, tos, v) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // General rule: With at least one recipient, the call reverts exactly when the low-level call to caddress for transferFrom fails.
            // Since caddress may be an arbitrary address, we cannot easily check the internal call result directly, but we can observe that if caddress is the test contract itself, it has no transferFrom function, so the internal call will fail, causing a revert.
            // However, to avoid hard-coding, the rule should be general. The contract's transfer function does not return false; it either returns true or reverts.
            // A more general rule: transfer never returns false; it returns true on success.
            // But we need to assert after the call. The call may revert, in which case we cannot assert it returned true.
            // The rule: if the call does not revert, it must be that tos.length > 0 and all internal calls succeeded, which is trivially true because otherwise it would revert.
            // To make it non-trivial, we assert that the call completes without reverting when tos is non-empty and caddress is a contract that implements transferFrom successfully.
            // But we cannot create such a contract. So we rely on the fact that the test contract is msg.sender and deployed c. We cannot force caddress to be a valid contract.
            // Another angle: the contract requires _tos.length > 0. So if we pass empty array, it must revert.
            // We already know that if tos.length == 0, the precondition fails, so we don't call c.transfer.
            // But we can test the empty case separately.
            // Since the rule must be general for all inputs, we can split: if tos.length == 0, the call must revert (due to require).
            // That is a clear rule: transfer reverts if and only if tos.length == 0 OR the internal call fails.
            // However, we cannot know if the internal call fails, but we can assert the converse: if tos.length > 0 and the call does not revert, then it must have returned true.
            // But that is trivial. We need a rule that a faulty version would break.
            // Consider a faulty version that does not check the return value of the low-level call. Then it would not revert even if the internal call fails.
            // But we cannot observe internal failure directly. However, we can observe that if caddress is a contract that returns false, the correct contract would revert, while a faulty one would not.
            // We cannot deploy such a contract, but we can use the test contract itself: does it have a fallback or receive? It does not. So calling transferFrom on it will fail (no function).
            // So if caddress is the test contract address (address(this)), the internal call should fail, causing c.transfer to revert.
            // But we must not hard-code addresses; we can use address(this) as caddress? That is not hard-coded, it's dynamic.
            // But then the rule would be: if caddress == address(this), then transfer must revert (since this contract lacks transferFrom).
            // That is a specific input, not general. The property-based test checker will try all inputs, so it might find a counterexample where caddress is not address(this).
            // So we need a rule that holds regardless of caddress.
            // The contract's require(_tos.length > 0) means it reverts for empty array. That is a general rule.
            // Also, if the loop completes, it returns true. So if it does not revert and tos.length > 0, it must have returned true.
            // But we don't capture the return value. We can capture: bool result = c.transfer(...). But then if it reverts, try/catch captures that.
            // So rule: if tos.length == 0, it reverts. If tos.length > 0, it either reverts (due to internal failure) or returns true.
            // That is a general rule: the transfer function never returns false. It either reverts or returns true.
            // A faulty version could return false, which would break the rule.
            // So we assert: if the call did not revert, the returned value must be true.
            // But we need to capture the return value. In the try block, we can store it.
            // Let's do that.
            bool result;
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                result = r;
                reverted = false;
            } catch {
                reverted = true;
            }
            if (!reverted) {
                assert(result == true);
            } else {
                // If it reverted, the rule about empty array must hold: if tos.length == 0, it must revert.
                // But we only call if tos.length > 0, so that's not tested here.
                // We can also assert that if it reverted, it's not because of a false return.
                // That's trivial.
                assert(true);
            }
        } else {
            // Test the empty array case: it must revert.
            try c.transfer(from, caddress, tos, v) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted == true);
        }
    }
}

